const nextInvoiceNo = `-- name: NextInvoiceNo :one
SELECT COALESCE(MAX(invoice_no), 0)::INTEGER + 1 AS next
FROM invoices WHERE kind = $1::invoice_kind
`

func (q *Queries) NextInvoiceNo(ctx context.Context, kind InvoiceKind) (int32, error) {
	row := q.db.QueryRow(ctx, nextInvoiceNo, kind)
	var next int32
	err := row.Scan(&next)
	return next, err
}

const overdueInvoices = `-- name: OverdueInvoices :many
SELECT i.id, i.invoice_no, i.due_date, c.name AS customer_name,
       (COALESCE((SELECT SUM(l.line_total + l.tax_amount)
                    FROM invoice_lines l WHERE l.invoice_id = i.id), 0)
        - COALESCE((SELECT SUM(p.amount)
                      FROM invoice_payments p WHERE p.invoice_id = i.id), 0)
       )::numeric AS outstanding
FROM invoices i
JOIN customers c ON c.id = i.customer_id
WHERE i.kind = 'invoice'
  AND i.status IN ('issued', 'part_paid')
  AND i.due_date IS NOT NULL
  AND i.due_date < CURRENT_DATE
ORDER BY i.due_date
`

type OverdueInvoicesRow struct {
	ID           uuid.UUID      `json:"id"`
	InvoiceNo    int32          `json:"invoice_no"`
	DueDate      pgtype.Date    `json:"due_date"`
	CustomerName string         `json:"customer_name"`
	Outstanding  pgtype.Numeric `json:"outstanding"`
}

// Issued invoices past their due date with money still on them, for the
// alert evaluator.
func (q *Queries) OverdueInvoices(ctx context.Context) ([]OverdueInvoicesRow, error) {
	rows, err := q.db.Query(ctx, overdueInvoices)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OverdueInvoicesRow{}
	for rows.Next() {
		var i OverdueInvoicesRow
		if err := rows.Scan(
			&i.ID,
			&i.InvoiceNo,
			&i.DueDate,
			&i.CustomerName,
			&i.Outstanding,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

